using FluentAssertions;
using GrowthBook.Providers;
using Microsoft.Extensions.Logging.Abstractions;
using Newtonsoft.Json.Linq;
using Xunit;

namespace GrowthBook.Tests.CustomTests;

/// <summary>
/// Plain (non-operator) condition values compare with JavaScript coercion, as in the reference SDK.
/// Expected values were generated by running each case through the JS SDK's evalCondition.
/// </summary>
public class PlainEqualityConditionTests
{
    private readonly ConditionEvaluationProvider _provider = new(new NullLogger<ConditionEvaluationProvider>());

    [Theory]
    [InlineData("{\"n\":\"10\"}", "{\"n\":10}", true)]
    [InlineData("{\"n\":\"1.5\"}", "{\"n\":1.5}", true)]
    [InlineData("{\"n\":\"1e+21\"}", "{\"n\":1e+21}", true)]
    [InlineData("{\"n\":\"1e-7\"}", "{\"n\":1e-7}", true)]
    [InlineData("{\"n\":\"10000000000000000\"}", "{\"n\":10000000000000000}", true)]
    [InlineData("{\"n\":\"true\"}", "{\"n\":true}", true)]
    [InlineData("{\"n\":\"false\"}", "{\"n\":false}", true)]
    [InlineData("{\"n\":\"null\"}", "{\"n\":null}", true)]
    [InlineData("{\"n\":\"null\"}", "{}", true)]
    [InlineData("{\"n\":\"undefined\"}", "{}", false)]
    [InlineData("{\"n\":\"a,b\"}", "{\"n\":[\"a\",\"b\"]}", true)]
    [InlineData("{\"n\":\"[object Object]\"}", "{\"n\":{\"a\":1}}", true)]
    [InlineData("{\"n\":\"10\"}", "{\"n\":\"10\"}", true)]
    [InlineData("{\"n\":\"10\"}", "{\"n\":\"010\"}", false)]
    [InlineData("{\"n\":10}", "{\"n\":\"10\"}", true)]
    [InlineData("{\"n\":10}", "{\"n\":\" 10 \"}", true)]
    [InlineData("{\"n\":0}", "{\"n\":\"\"}", true)]
    [InlineData("{\"n\":1}", "{\"n\":true}", true)]
    [InlineData("{\"n\":0}", "{\"n\":false}", true)]
    [InlineData("{\"n\":0}", "{\"n\":null}", true)]
    [InlineData("{\"n\":0}", "{}", true)]
    [InlineData("{\"n\":1}", "{\"n\":\"abc\"}", false)]
    [InlineData("{\"n\":1}", "{\"n\":1}", true)]
    [InlineData("{\"n\":1.5}", "{\"n\":\"1.5\"}", true)]
    [InlineData("{\"n\":12}", "{\"n\":\"0xC\"}", true)]
    [InlineData("{\"n\":5}", "{\"n\":[5]}", true)]
    [InlineData("{\"n\":5}", "{\"n\":[5,6]}", false)]
    [InlineData("{\"n\":0}", "{\"n\":{}}", false)]
    [InlineData("{\"b\":false}", "{\"b\":\"false\"}", false)]
    [InlineData("{\"b\":true}", "{\"b\":\"false\"}", true)]
    [InlineData("{\"b\":true}", "{\"b\":\"0\"}", true)]
    [InlineData("{\"b\":false}", "{\"b\":0}", true)]
    [InlineData("{\"b\":false}", "{\"b\":\"\"}", true)]
    [InlineData("{\"b\":false}", "{}", false)]
    [InlineData("{\"b\":false}", "{\"b\":null}", false)]
    [InlineData("{\"b\":true}", "{\"b\":1}", true)]
    [InlineData("{\"b\":true}", "{\"b\":\"true\"}", true)]
    [InlineData("{\"b\":true}", "{\"b\":[]}", true)]
    [InlineData("{\"b\":true}", "{\"b\":{}}", true)]
    [InlineData("{\"b\":true}", "{\"b\":2.5}", true)]
    [InlineData("{\"n\":null}", "{}", true)]
    [InlineData("{\"n\":null}", "{\"n\":null}", true)]
    [InlineData("{\"n\":null}", "{\"n\":0}", false)]
    [InlineData("{\"n\":null}", "{\"n\":\"\"}", false)]
    [InlineData("{\"a\":[1,2]}", "{\"a\":[1,2]}", true)]
    [InlineData("{\"a\":[1,2]}", "{\"a\":[1,2]}", true)]
    [InlineData("{\"a\":[1,2]}", "{\"a\":[2,1]}", false)]
    [InlineData("{\"a\":[\"1\"]}", "{\"a\":[1]}", false)]
    [InlineData("{\"o\":{\"x\":1,\"y\":2}}", "{\"o\":{\"y\":2,\"x\":1}}", false)]
    [InlineData("{\"o\":{\"x\":1}}", "{\"o\":{\"x\":1}}", true)]
    [InlineData("{\"o\":{}}", "{\"o\":{}}", true)]
    [InlineData("{\"o\":{}}", "{}", false)]
    [InlineData("{\"n\":1}", "{\"n\":1.0}", true)]
    [InlineData("{\"n\":1.0}", "{\"n\":1}", true)]
    [InlineData("{\"n\":\"1\"}", "{\"n\":1.0}", true)]
    [InlineData("{\"a\":[1,2]}", "{\"a\":[1.0,2]}", true)]
    public void EvalCondition_PlainValue_MatchesJavaScriptEquality(string condition, string attributes, bool expected)
    {
        _provider.EvalCondition(JObject.Parse(attributes), JObject.Parse(condition)).Should().Be(expected);
    }
}
